import{_ as a,y as c,a as i,o as l,a2 as r,D as s,g as t,I as o}from"./chunks/framework.DCcmcJcL.js";const C=JSON.parse('{"title":"Currencies","description":"","frontmatter":{},"headers":[],"relativePath":"settings/currencies.md","filePath":"settings/currencies.md","lastUpdated":1789441803000}'),d={name:"settings/currencies.md"};function h(u,e,g,p,y,m){const n=c("ImagePopup");return l(),i("div",null,[e[2]||(e[2]=r('<h1 id="currencies" tabindex="-1">Currencies <a class="header-anchor" href="#currencies" aria-label="Permalink to &quot;Currencies&quot;">​</a></h1><p>Add each currency you want to show prices in, then turn it on for the channels that should offer it. A currency&#39;s settings control how its prices look, for example <code>$1,234.50</code> or <code>1.234,50 €</code>.</p><p>Product prices are entered in your store&#39;s base currency, which is chosen when Bagisto is installed and can&#39;t be changed in the admin panel. To show correct prices in another currency, also add an <a href="./exchange-rates.html">exchange rate</a> for it.</p><h2 id="your-currencies" tabindex="-1">Your currencies <a class="header-anchor" href="#your-currencies" aria-label="Permalink to &quot;Your currencies&quot;">​</a></h2><p>Go to <strong>Settings &gt;&gt; Currencies</strong> to see every currency with its <strong>ID</strong>, <strong>Name</strong> and <strong>Code</strong>. Search by name or code, or use <strong>Filter</strong> to narrow the list.</p>',5)),s(n,{src:"/images/settings/currencies.png",alt:"Currencies grid listing the store's currencies with the Create Currency button"}),e[3]||(e[3]=t("h2",{id:"create-a-currency",tabindex:"-1"},[o("Create a currency "),t("a",{class:"header-anchor",href:"#create-a-currency","aria-label":'Permalink to "Create a currency"'},"​")],-1)),t("ol",null,[e[1]||(e[1]=r("<li><p>Go to <strong>Settings &gt;&gt; Currencies</strong>.</p></li><li><p>Click <strong>Create Currency</strong>. The <strong>Create New Currency</strong> form opens.</p></li><li><p>Enter the <strong>Code</strong> and <strong>Name</strong>, such as <code>KES</code> and <strong>Kenyan Shilling</strong>.</p></li><li><p>Enter the <strong>Symbol</strong>, such as <code>KSh</code>.</p></li><li><p>Enter the <strong>Decimal</strong>, <strong>Group Separator</strong> and <strong>Decimal Separator</strong>.</p></li><li><p>Choose the <strong>Currency Position</strong>.</p></li>",6)),t("li",null,[e[0]||(e[0]=t("p",null,[o("Click "),t("strong",null,"Save Currency"),o(".")],-1)),s(n,{src:"/images/settings/create-currency.png",alt:"Create New Currency form for the Kenyan Shilling"})])]),e[4]||(e[4]=r('<p>The message <em>Currency created successfully.</em> appears and the currency is added to the list.</p><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>Code</strong></td><td>The three-letter currency code, such as <code>USD</code>, <code>EUR</code> or <code>KES</code>. Each code can be used only once, and you can&#39;t change it later.</td></tr><tr><td><strong>Name</strong></td><td>The name of the currency.</td></tr><tr><td><strong>Symbol</strong></td><td>The symbol shown with prices, such as <code>$</code> or <code>KSh</code>. If you leave it empty, the usual symbol for the code is used, or the code itself when a <strong>Currency Position</strong> is chosen.</td></tr><tr><td><strong>Decimal</strong></td><td>How many digits to show after the decimal separator, from 0 to 9, such as <code>2</code>.</td></tr><tr><td><strong>Group Separator</strong></td><td>The character between groups of thousands, such as the comma in <code>1,000</code>. Use a comma, dot, apostrophe or space.</td></tr><tr><td><strong>Decimal Separator</strong></td><td>The character before the decimals, such as the dot in <code>10.50</code>. Use a comma or dot.</td></tr><tr><td><strong>Currency Position</strong></td><td>Where the symbol appears: <strong>Left</strong> (<code>$10</code>), <strong>Left With Space</strong> (<code>$ 10</code>), <strong>Right</strong> (<code>10$</code>) or <strong>Right With Space</strong> (<code>10 $</code>).</td></tr></tbody></table><h3 id="the-format-needs-a-position" tabindex="-1">The format needs a position <a class="header-anchor" href="#the-format-needs-a-position" aria-label="Permalink to &quot;The format needs a position&quot;">​</a></h3><p><strong>Decimal</strong>, <strong>Group Separator</strong> and <strong>Decimal Separator</strong> are used only when you choose a <strong>Currency Position</strong>. If you leave the position unselected, prices follow the usual format of the language the shopper is browsing in, with your symbol.</p><h2 id="offer-the-currency-on-a-channel" tabindex="-1">Offer the currency on a channel <a class="header-anchor" href="#offer-the-currency-on-a-channel" aria-label="Permalink to &quot;Offer the currency on a channel&quot;">​</a></h2><ol><li>Go to <strong>Settings &gt;&gt; Channels</strong>.</li><li>Click the edit icon of the channel.</li><li>In <strong>Currencies and Locales</strong>, select the currency under <strong>Currencies</strong>.</li><li>To show prices in it by default, choose it as the <strong>Default Currency</strong>.</li><li>Click <strong>Save Channel</strong>.</li></ol><p>Shoppers can now choose the currency on that channel&#39;s storefront.</p><h2 id="edit-or-delete-a-currency" tabindex="-1">Edit or delete a currency <a class="header-anchor" href="#edit-or-delete-a-currency" aria-label="Permalink to &quot;Edit or delete a currency&quot;">​</a></h2><p>To edit a currency:</p><ol><li>Go to <strong>Settings &gt;&gt; Currencies</strong>.</li><li>Click the edit icon of the currency. The <strong>Edit Currency</strong> form opens.</li><li>Change the currency&#39;s details. The code can&#39;t be changed.</li><li>Click <strong>Save Currency</strong>.</li></ol><p>The message <em>Currency updated successfully.</em> appears.</p><p>To remove a currency:</p><ol><li>Go to <strong>Settings &gt;&gt; Currencies</strong>.</li><li>Click the delete icon of the currency.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><ul><li>A store must keep at least one currency.</li><li>A currency that a channel uses as its <strong>Default Currency</strong> can&#39;t be deleted. Choose another default currency for the channel first.</li><li>Deleting a currency also removes it from every channel that offers it, and deletes its exchange rate.</li><li>Don&#39;t delete your store&#39;s base currency, because product prices are entered in it.</li></ul>',14))])}const _=a(d,[["render",h]]);export{C as __pageData,_ as default};
